:root {
  --color-bg: #f2ead8;
  --color-border: #8b6c42;
  --color-border-light: #c4a97a;
  --color-header-bg: #5c3d1e;
  --color-header-text: #f7eed8;
  --color-subtitle: #d4b896;
  --color-number: #d4a853;
  --color-meta-bg: #e8dcc4;
  --color-meta-label: #8b6c42;
  --color-meta-value: #3a2710;
  --color-row-alt: #ede4ce;
  --color-specimen-name: #2e1a08;
  --color-specimen-latin: #7a5c38;
  --color-safe-bg: #d4edda;
  --color-safe-text: #2e6b3e;
  --color-danger-bg: #f8d7da;
  --color-danger-text: #842029;
  --color-count: #5c3d1e;
  --color-dot-a: #e8a020;
  --color-dot-b: #8b4513;
  --color-dot-c: #4a7c4e;
  --color-dot-d: #c8c8b0;
  --color-footer-bg: #5c3d1e;
  --color-footer-text: #f7eed8;
  --color-stamp: #d4a853;
  --color-note: #d4b896;
}

.foraging-log {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  width: 480px;
  overflow: hidden;
  font-size: 13px;
}

.log-header {
  background-color: var(--color-header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
}

.log-icon {
  font-size: 26px;
  line-height: 1;
}

.log-title-group {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--color-header-text);
  margin: 0;
  line-height: 1.2;
  letter-spacing: 0.04em;
}

.log-subtitle {
  font-size: 11px;
  color: var(--color-subtitle);
  margin: 0;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.log-number {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-number);
  letter-spacing: 0.02em;
}

.log-meta {
  display: flex;
  border-bottom: 1px solid var(--color-border-light);
  background-color: var(--color-meta-bg);
}

.meta-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 8px;
  gap: 2px;
  border-right: 1px solid var(--color-border-light);
}

.meta-item:last-child {
  border-right: none;
}

.meta-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-meta-label);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.meta-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-meta-value);
}

.specimens {
  display: flex;
  flex-direction: column;
  padding: 6px 0;
}

.specimen-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
}

.specimen-row:nth-child(even) {
  background-color: var(--color-row-alt);
}

.specimen-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-a { background-color: var(--color-dot-a); }
.dot-b { background-color: var(--color-dot-b); }
.dot-c { background-color: var(--color-dot-c); }
.dot-d { background-color: var(--color-dot-d); border: 1px solid var(--color-border-light); }

.specimen-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-specimen-name);
  width: 82px;
  flex-shrink: 0;
}

.specimen-latin {
  font-size: 11px;
  color: var(--color-specimen-latin);
  font-style: italic;
  flex: 1;
}

.specimen-status {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 2px 7px;
  border-radius: 10px;
  flex-shrink: 0;
}

.status-safe {
  background-color: var(--color-safe-bg);
  color: var(--color-safe-text);
}

.status-danger {
  background-color: var(--color-danger-bg);
  color: var(--color-danger-text);
}

.specimen-count {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-count);
  width: 38px;
  text-align: right;
  flex-shrink: 0;
}

.log-footer {
  background-color: var(--color-footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
}

.footer-note {
  display: flex;
  align-items: center;
  gap: 6px;
}

.note-icon {
  font-size: 13px;
  line-height: 1;
}

.note-text {
  font-size: 11px;
  color: var(--color-note);
  font-style: italic;
}

.footer-stamp {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-stamp);
  letter-spacing: 0.14em;
  border: 2px solid var(--color-stamp);
  padding: 2px 8px;
  border-radius: 3px;
}
